def make_entries(text):
    result=[]
    for line in text.splitlines():
        id,name,group,summary,explain,boundary,book,start,end=line.split('|')
        result.append(dict(id=id,name=name,group=group,summary=summary,explain=explain,boundary=boundary,citations=[citation(book,int(start),int(end))]))
    return result

